(function(root){
'use strict';
let worker=null,objectURL=null,running=false,data=null,current=null,guard=()=>true;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),names={fire:'火',water:'水',thunder:'雷',ice:'冰',dragon:'龙'},signed=n=>(n>0?'+':'')+n;
function busy(on){running=on;for(const el of $('simControls').querySelectorAll('input,select,textarea,button'))el.disabled=on;$('simStop').disabled=!on;}
function dispose(){worker?.terminate();worker=null;if(objectURL)URL.revokeObjectURL(objectURL);objectURL=null;}
function status(s){$('simStatus').textContent=s;}
function selectArmor(keep=false){const q=$('simArmorSearch').value.trim(),part=$('simPart').value,old=$('simArmor').value,as=data.armors.filter(a=>a.pool>0&&a.part===part&&(!q||a.name.includes(q)));
 $('simArmor').innerHTML=as.map(a=>'<option value="'+a.id+'">'+esc(a.name)+' · RARE '+a.rarity+'</option>').join('');if(keep&&as.some(a=>a.id===old))$('simArmor').value=old;armorSummary();}
function armorSummary(){const a=data.armors.find(a=>a.id===$('simArmor').value);$('simArmorSummary').textContent=a?'基础防御 '+a.defense+' · 孔位 '+(a.slots.join('-')||'无')+' · Pool '+a.pool+' · 预算 '+a.budget+' · '+a.skills.map(s=>data.skills.find(k=>k.id===s.skill_id).name+' '+s.level).join(' / '):'没有匹配的可炼化防具';for(const option of $('simMode').options)option.disabled=!!a&&a.pool===13&&['skills','slots'].includes(option.value);if($('simMode').selectedOptions[0]?.disabled)$('simMode').value='normal';}
function skillOptions(){const q=$('simSkillSearch').value.trim(),ss=data.skills.filter(s=>!q||s.name.includes(q));$('simTargetSkill').innerHTML='<option value="-1">不限定技能</option>'+ss.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join('');if(q)$('simTargetSkill').value=ss.length?String(ss[0].id):'-1';}
function sortingSkills(prefix){const q=$(prefix+'SkillSearch').value.trim().toLowerCase(),ss=data.skills.filter(s=>!q||s.name.includes(q)||(s.nameEn||'').toLowerCase().includes(q));$(prefix+'Skill').innerHTML=ss.length?ss.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join(''):'<option value="-1">没有匹配技能</option>';}
function requestPage(page=0){if(!worker)return;const sort=$('simViewSort').value,skill=Number($('simViewSkill').value),skillMetric=$('simViewSkillMetric').value;$('simViewSkillFields').classList?.toggle('hidden',!sort.startsWith('specificSkill'));worker.postMessage({type:'page',page,sort,skill,skillMetric});}
function label(a){if(a.skillId!=null)return esc(data.skills.find(s=>s.id===a.skillId)?.name)+' '+signed(a.value);return (a.category===19?'孔位增长':a.category===13?'防御':names[a.attribute]+'耐性')+' '+signed(a.value);}
function show(m){current=m;const s=m.stats,c=m.config,seconds=(m.elapsedMs/1000).toFixed(1),pct=s.completed/c.count*100;
 $('simProgress').value=s.completed;$('simProgress').max=c.count;
 $('simStats').innerHTML=[['已模拟',s.completed.toLocaleString()+' / '+c.count.toLocaleString()],['条件命中',s.matches.toLocaleString()+'（'+(s.completed?s.matches/s.completed*100:0).toFixed(3)+'%）'],['最高防御',s.completed?s.maxDefense:'—'],['平均防御',s.completed?(s.defenseSum/s.completed).toFixed(2):'—'],['内部抽选',s.attempts.toLocaleString()],['保留组合',m.total+' / '+c.limit]].map(([k,v])=>'<span>'+k+' <b>'+v+'</b></span>').join('');
 $('simAppliedQuery').textContent=c.query?'本次命中指令：'+c.query:'本次未设置命中指令';
 status(data.armors.find(a=>a.id===c.armorId).name+' · '+root.ForgeAugmentSim.MODES[c.mode]+' · '+(m.type==='done'?'模拟完成':m.type==='stopped'?'已停止并保留结果':running?'模拟中':'已保留结果')+' · '+pct.toFixed(1)+'% · '+seconds+'秒 · 种子 '+c.seed+' · 预算耗尽 '+s.terminations.budget+' / 七条结束 '+s.terminations.records+' / 连续失败结束 '+s.terminations.failures);
 const sorting=m.viewSort?.startsWith('specificSkill')?{id:m.viewSkill,metric:m.viewSkillMetric}:c.sort.startsWith('specificSkill')&&m.viewSort==='retained'?{id:c.sortSkill,metric:c.sortSkillMetric}:null;
 $('simList').innerHTML=m.rows.map((r,i)=>'<article class="sim-result"><div class="sim-result-top"><strong>#'+(m.page*25+i+1)+'　防御 '+r.defense+'（'+signed(r.defenseDelta)+'）</strong><span>出现 '+r.count+' 次 · '+(r.count/s.completed*100).toFixed(3)+'%</span></div><div class="sim-result-meta">孔位 '+(r.slots.join('-')||'无')+' · 新增技能 '+r.skillAdds+'级 · 新增技能cost '+r.skillCost+' · 记录 '+r.atoms.length+'/7 · cost '+r.cost+'/'+data.armors.find(a=>a.id===c.armorId).budget+(sorting?' · 排序技能等级 '+root.ForgeAugmentSim.skillLevel(r,sorting.id,sorting.metric):'')+'</div><div class="augment-list">'+r.atoms.map(a=>'<span class="augment'+(a.value<0?' negative':'')+'">'+(a.fallback?'防御收尾 · ':'')+label(a)+'</span>').join('')+'</div><p class="sim-result-meta">最终技能：'+r.skills.map(s=>esc(data.skills.find(k=>k.id===s.skill_id)?.name)+' '+s.level).join(' / ')+'</p><p class="sim-result-meta">单件耐性：'+Object.entries(names).map(([k,n])=>n+' '+r.resistances[k]).join('　')+'</p></article>').join('')||'<p class="muted">尚无结果。</p>';
 if(sorting){const skill=data.skills.find(s=>s.id===sorting.id);$('simAppliedSort').textContent='当前按'+(skill?.name||'指定技能')+'的'+(sorting.metric==='added'?'炼化新增等级':'最终单件等级')+'排序';}else $('simAppliedSort').textContent='';
 const pages=Math.max(1,Math.ceil(m.total/25));$('simPageInfo').textContent=(m.page+1)+' / '+pages;$('simPrev').disabled=m.page<=0;$('simNext').disabled=m.page+1>=pages;
}
function start(){if(!guard()){status('请先停止配装搜索，再开始炼化模拟。');return;}let replaced=false;$('simError').textContent='';
 try{let seed=$('simSeed').value.trim();if(seed===''){const a=new Uint32Array(1);crypto.getRandomValues(a);seed=a[0];$('simSeed').value=seed;}
  const config={armorId:$('simArmor').value,mode:$('simMode').value,count:Number($('simCount').value),limit:Number($('simKeep').value),sort:$('simSort').value,sortSkill:Number($('simSortSkill').value),sortSkillMetric:$('simSortSkillMetric').value||'final',query:$('simQuery').value,seed:Number(seed),targetSkill:Number($('simTargetSkill').value),targetLevel:Number($('simTargetLevel').value)};
  root.ForgeAugmentSim.createBatch(data,config);dispose();replaced=true;current=null;$('simList').innerHTML='';$('simAppliedQuery').textContent='';$('simAppliedSort').textContent='';const embedded=$('embeddedAugmentWorker');let url;
  if(embedded){const code=new TextDecoder().decode(Uint8Array.from(atob(embedded.textContent.trim()),c=>c.charCodeAt(0)));objectURL=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));url=objectURL;}else url=new URL('./augment-worker.js',location.href);
  worker=new Worker(url);const active=worker;busy(true);root.ForgeSimUI.started=performance.now();status('准备模拟…');$('simProgress').value=0;$('simViewSort').value='retained';
  worker.onmessage=({data:m})=>{if(worker!==active)return;if(m.type==='viewError'){$('simError').textContent=m.message;return;}if(m.type==='error'){busy(false);dispose();$('simError').textContent=m.message;status('模拟中止，未完成的抽选不计入样本。');return;}if(m.type==='done'||m.type==='stopped')busy(false);show(m);};
  worker.onerror=e=>{if(worker!==active)return;busy(false);dispose();$('simError').textContent=e.message||'炼化Worker无法运行';};
  worker.postMessage({type:'start',data:{armors:[data.armors.find(a=>a.id===config.armorId)],skills:data.skills,atoms:data.atoms,augmentationLottery:data.augmentationLottery},config});
 }catch(e){busy(false);if(replaced)dispose();$('simError').textContent=e.message;}}
function initialize(d,canStart){data=d;guard=canStart||guard;$('simArmorSearch').oninput=()=>selectArmor();$('simPart').onchange=()=>selectArmor();$('simArmor').onchange=armorSummary;$('simSkillSearch').oninput=skillOptions;$('simStart').onclick=start;$('simStop').onclick=()=>worker?.postMessage({type:'stop'});$('simClear').onclick=()=>{dispose();busy(false);current=null;$('simAppliedQuery').textContent='';$('simAppliedSort').textContent='';$('simError').textContent='';$('simList').innerHTML='';$('simStats').innerHTML='';$('simProgress').value=0;$('simPageInfo').textContent='0 / 0';$('simPrev').disabled=$('simNext').disabled=true;status('结果已清空，内存已释放。');};$('simQueryExample').onclick=()=>{$('simQuery').value='grade.B >= 1 AND removed = 0';};$('simSortSkillSearch').oninput=()=>sortingSkills('simSort');$('simViewSkillSearch').oninput=()=>{sortingSkills('simView');requestPage();};$('simViewSkill').onchange=$('simViewSkillMetric').onchange=()=>requestPage();$('simViewSort').onchange=()=>{ $('simViewSkillFields').classList?.toggle('hidden',!$('simViewSort').value.startsWith('specificSkill'));requestPage();};$('simPrev').onclick=()=>requestPage((current?.page||0)-1);$('simNext').onclick=()=>requestPage((current?.page||0)+1);selectArmor();skillOptions();sortingSkills('simSort');sortingSkills('simView');}
root.ForgeSimUI={initialize,isRunning:()=>running,started:0};
})(globalThis);
